insert into public.events (actor, entity, entity_id, action, payload, created_at)
select case v.who when 'acc' then q.created_by when 'pm' then (select id from public.profiles where role = 'pm' and full_name = 'Võ Quỳnh Anh' limit 1) else (select id from public.profiles where role = 'ceo' order by created_at limit 1) end,
  'quotes', q.id::text, v.action, '{"seed":"journey-1.8"}'::jsonb, v.at::timestamptz
from v join public.quotes q on q.code = v.code and q.id::text in (select row_id from public.seed_registry where table_name = 'quotes')
where not exists (select 1 from public.events e where e.entity = 'quotes' and e.entity_id = q.id::text and e.action = v.action and e.created_at = v.at::timestamptz);